import React, { useState, useRef, useEffect } from 'react';
import { Upload, Download, Save, Edit3, Plus, Trash2, Eye, LayoutDashboard, ChevronDown, Users } from 'lucide-react';
import CustomerManagement from './CustomerManagement';
import './App.css';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import Dashboard from './Dashboard';
import FeedbackCommandCenter from './FeedbackCommandCenter';
import CustomerPage from './CustomerPage';
import BusinessSwitcher from './BusinessSwitcher';
import BusinessModal from './BusinessModal';
import { customerService } from './lib/supabase';

const InvoiceGenerator = ({ currentView, setCurrentView, savedInvoices, setSavedInvoices, editingInvoice, setEditingInvoice, customers }) => {
  const [isListening, setIsListening] = useState(false);
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  const [showCustomerManagement, setShowCustomerManagement] = useState(false);
  const [localCustomers, setLocalCustomers] = useState(customers || []);
  const [invoiceData, setInvoiceData] = useState({
    company: {
      name: 'Your Company Name',
      address: '123 Business Street',
      city: 'City',
      state: 'State',
      zip: '12345',
      email: 'contact@company.com',
      phone: '(555) 123-4567'
    },
    client: {
      name: '',
      address: '',
      email: ''
    },
    invoice: {
